mapper.select:
SELECT id, feedback_source_id AS feedback_id, handler_user_id AS actor_id,
       event_type, old_status, new_status, event_reason AS reason, created_at
FROM t_feedback_disposition_event
WHERE event_type IN ('STATUS_CHANGED', 'REOPENED')
  AND handler_user_id <> #{user}
AND id < #{before}
ORDER BY id DESC
LIMIT #{limit}
